constexpr std::uint64_t kMiB = std::uint64_t{1024} * 1024;
constexpr std::size_t kHashBlock = std::size_t{64} * 1024;

constexpr std::array<std::string_view, 3> kKindNames = {"asr", "vad", "llm"};
constexpr std::array<std::string_view, 3> kClassNames = {"mobile-small", "mobile", "desktop"};

std::unexpected<ManifestError> Bad(std::string message) {
  return std::unexpected(ManifestError{.message = std::move(message)});
}

std::optional<std::uint8_t> HexDigit(char c) {
  if (c >= '0' && c <= '9') {
    return static_cast<std::uint8_t>(c - '0');
  }
  if (c >= 'a' && c <= 'f') {
    return static_cast<std::uint8_t>(c - 'a' + 10);
  }
  return std::nullopt;
}

std::optional<crypto::Sha256Digest> ParseSha256(std::string_view hex) {
  crypto::Sha256Digest out{};
  if (hex.size() != out.size() * 2) {
    return std::nullopt;
  }
  for (std::size_t i = 0; i < out.size(); ++i) {
    const auto hi = HexDigit(hex[2 * i]);
    const auto lo = HexDigit(hex[(2 * i) + 1]);
    if (!hi || !lo) {
      return std::nullopt;
    }
    out.at(i) =
        static_cast<std::byte>((static_cast<unsigned>(*hi) << 4U) | static_cast<unsigned>(*lo));
  }
  return out;
}

// The file a URL names, if it's one we'd put in the models directory: no
// separators, no leading dot, nothing but [A-Za-z0-9._-].
std::optional<std::string> FileFromUrl(std::string_view url) {
  constexpr std::string_view kScheme = "https://";
  if (!url.starts_with(kScheme)) {
    return std::nullopt;
  }
  const std::string_view file = url.substr(url.rfind('/') + 1);
  const bool safe = std::ranges::all_of(file, [](char c) {
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' ||
           c == '_' || c == '-';
  });
  if (file.empty() || file.front() == '.' || !safe) {
    return std::nullopt;
  }
  return std::string(file);
}

// An optional non-negative integer field; nullopt if present but not one.
std::optional<std::uint64_t> OptionalCount(const json &o, const char *name) {
  const auto it = o.find(name);
  if (it == o.end()) {
    return 0;
  }
  if (!it->is_number_unsigned()) {
    return std::nullopt;
  }
  return it->get<std::uint64_t>();
}

const std::string *StringField(const json &o, const char *name) {
  const auto it = o.find(name);
  return it != o.end() && it->is_string() ? it->get_ptr<const std::string *>() : nullptr;
}

// GCOVR_EXCL_BR_START: in ParseModel() and Parse(), the branches gcov
// reports uncovered are gcc's exception cleanup for the strings and json
// temporaries; every validation rule has a case in models_test.cpp.
std::expected<Model, ManifestError> ParseModel(const json &m) {
  if (!m.is_object()) {
    return Bad("every model must be an object");
  }
  Model out;
  const std::string *id = StringField(m, "id");
  if (id == nullptr || id->empty()) {
    return Bad("a model has no id");
  }
  out.id = *id;
  const std::string where = "model \"" + out.id + "\": ";
  const std::string *kind = StringField(m, "kind");
  const auto parsed_kind = kind != nullptr ? ParseKind(*kind) : std::nullopt;
  if (!parsed_kind) {
    return Bad(where + "kind must be asr, vad or llm");
  }
  out.kind = *parsed_kind;
  const std::string *url = StringField(m, "url");
  const auto file = url != nullptr ? FileFromUrl(*url) : std::nullopt;
  if (!file) {
    return Bad(where + "url must be https and end in a plain file name");
  }
  out.url = *url;
  out.file = *file;
  const std::string *sha = StringField(m, "sha256");
  const auto digest = sha != nullptr ? ParseSha256(*sha) : std::nullopt;
  if (!digest) {
    return Bad(where + "sha256 must be 64 lowercase hex digits");
  }
  out.sha256 = *digest;
  const auto bytes = m.find("bytes");
  if (bytes == m.end() || !bytes->is_number_unsigned() || bytes->get<std::uint64_t>() == 0) {
    return Bad(where + "bytes must be a positive integer");
  }
  out.bytes = bytes->get<std::uint64_t>();
  const auto ram = OptionalCount(m, "min_ram_mb");
  if (!ram) {
    return Bad(where + "min_ram_mb must be a non-negative integer");
  }
  out.min_ram_mb = *ram;
  const auto classes = m.find("classes");
  if (classes == m.end() || !classes->is_array() || classes->empty()) {
    return Bad(where + "classes must be a non-empty list");
  }
  for (const json &c : *classes) {
    const auto cls = c.is_string() ? ParseClass(c.get<std::string>()) : std::nullopt;
    if (!cls) {
      return Bad(where + "classes are mobile-small, mobile and desktop");
    }
    out.classes.push_back(*cls);
  }
  const std::string *license = StringField(m, "license");
  out.license = license != nullptr ? *license : "";
  return out;
}
